#include <iostream>
#include <string>

void subsets(const std::string& items, std::size_t index, std::string current) {
    if (index == items.size()) { std::cout << (current.empty() ? "{}" : current) << '\n'; return; }
    subsets(items, index + 1, current);
    subsets(items, index + 1, current + items[index]);
}
int main() { subsets("ab", 0, ""); }
